"3h15":RL("3h15","El encuentro de dos mundos",["1492 y 1521","En 1492 Cristóbal Colón llegó a América. En 1521 Hernán Cortés, con ayuda de pueblos indígenas aliados, conquistó Tenochtitlan.",IMG("velasco","Valle de México")],["Luces y sombras","Hubo violencia, enfermedades y abusos que causaron gran sufrimiento. También llegaron el Evangelio, nuevas plantas, animales y saberes, y nació un pueblo mestizo.",{t:"cards",x:[["😢","sufrimiento"],["✝️","Evangelio"],["🐴","animales nuevos"],["🤝","mestizaje"]]}],["Defensores de los indígenas","Fray Bartolomé de las Casas y otros religiosos defendieron la dignidad de los indígenas: todos somos hijos de Dios.",{t:"emo",x:"✝️ 🤝 👥"}],["Juzgar con verdad","🤔","Un compañero dice que todo fue malo; otro, que todo fue bueno.","¿Qué opinas?",[["Que hubo cosas buenas y malas, y aprendemos a respetar a todos",1,"¡Muy bien! Así se estudia la historia."],["Que todo fue bueno",0,"Hubo mucho sufrimiento."],["Que todo fue malo",0,"También llegaron cosas buenas."]]],[["1492: Colón. 1521: caída de Tenochtitlan.","Luces y sombras.","Fray Bartolomé de las Casas."],["mestizaje"]],["¿Quién defendió a los indígenas?",["Era fraile dominico."],"Fray Bartolomé de las Casas."],
 [[["En 1521 cayó Tenochtitlan.",true],["¿En qué año llegó Colón a América?","1492","1810","1325"],["¿Quién defendió a los indígenas?","fray Bartolomé de las Casas","Hernán Cortés","Moctezuma"]],[["La conquista tuvo luces y sombras.",true],["¿Qué animal trajeron los españoles?","el caballo","el ajolote","el guajolote"]],[["¿Qué alimento americano conoció el mundo?","el maíz","el trigo","la uva"]]],"Todos somos hijos de Dios."),
"3h16":RL("3h16","Grandes misioneros",["Vasco de Quiroga","«Tata Vasco», obispo de Michoacán, organizó pueblos-hospital y enseñó oficios a los purépechas. Todavía hoy esos pueblos son famosos por sus artesanías.",{t:"emo",x:"🏺 🎸 ✝️"}],["Más misioneros","Fray Pedro de Gante fundó escuelas; fray Junípero Serra fundó misiones en Querétaro y California; el padre Kino recorrió Sonora.",{t:"cards",x:[["🏫","Pedro de Gante"],["⛪","Junípero Serra"],["🐎","padre Kino"]]}],["Vayan y enseñen","«Vayan por todo el mundo y anuncien el Evangelio» (Mc 16, 15).",IMG("apostoles","Apóstoles")],["Ser misionero hoy","📣","Un amigo no conoce a Jesús.","¿Qué haces?",[["Le hablo de Jesús con cariño y lo invito",1,"¡Muy bien! Eres misionero."],["Me burlo",0,"Respeta y comparte."],["Nunca le digo nada",0,"Comparte tu fe."]]],[["Vasco de Quiroga: Michoacán.","Pedro de Gante: escuelas.","Junípero Serra, padre Kino."],["misión"]],["¿Cómo llamaban los purépechas a Vasco de Quiroga?",["Tata = papá."],"Tata Vasco."],
 [[["Vasco de Quiroga trabajó en Michoacán.",true],["¿Qué fundó fray Pedro de Gante?","escuelas","fábricas","cines"],["¿A quién llamaban «Tata Vasco»?","Vasco de Quiroga","Hidalgo","Zapata"]],[["¿Qué santo fundó misiones en California?","fray Junípero Serra","san Juan Diego","santo Toribio"]],[["¿Qué estado recorrió el padre Kino?","Sonora","Yucatán","Oaxaca"]]],"Vayan y anuncien el Evangelio."),
"3h17":RL("3h17","Mártires mexicanos y la libertad religiosa",["Tiempos difíciles","Hacia 1926, el gobierno prohibió el culto católico: se cerraron templos y se persiguió a sacerdotes. Muchos fieles defendieron su fe.",IMG("cristoRey","Cristo Rey")],["Santos valientes","Santo Toribio Romo, sacerdote de Jalisco; san Cristóbal Magallanes; y <b>san José Sánchez del Río</b>, un niño de 14 años que no negó a Jesús. Gritaban: «¡Viva Cristo Rey!».",{t:"cards",x:[["⛪","santo Toribio"],["🧒","José Sánchez del Río"],["👑","¡Viva Cristo Rey!"]]}],["Perdonar como Jesús","Los mártires perdonaron a quienes les hacían daño. Hoy celebramos que en México hay libertad religiosa.",IMG("crucificado","Cristo crucificado")],["Defender mi fe","🙏","En la escuela un compañero se burla porque rezas.","¿Qué haces?",[["Sigo rezando con alegría y lo trato con respeto",1,"¡Muy bien! Como los santos."],["Dejo de rezar",0,"No te avergüences de Jesús."],["Le pego",0,"Los santos perdonaban."]]],[["Persecución religiosa (1926-1929).","Santo Toribio Romo, san José Sánchez del Río.","¡Viva Cristo Rey!"],["libertad religiosa"]],["¿Qué gritaban los mártires mexicanos?",["Un rey que es Jesús."],"¡Viva Cristo Rey!"],
 [[["San José Sánchez del Río era un niño.",true],["¿Qué gritaban los mártires?","¡Viva Cristo Rey!","¡Viva yo!","Nada"],["¿Qué hacían los mártires con sus enemigos?","los perdonaban","los odiaban","los insultaban"]],[["¿Qué santo sacerdote era de Jalisco?","santo Toribio Romo","san Martín de Porres","san Pablo"]],[["Hoy en México hay libertad religiosa.",true]]],"¡Viva Cristo Rey!"),
